#include <string>
#include <algorithm>
using namespace std;
bool is_prime(int n){ 
	if(n < 2) return 0;
	if(n == 2) return 1;
	if(n % 2 == 0) return 0;
	for(int i = 3; i * i <= n; i += 2){
		if(n % i == 0) return 0;
	}
	return 1;
}
int get_pal(int n){ 
	string s1 = to_string(n);
	string s2 = s1;
	s1.pop_back();
	reverse(s2.begin(), s2.end());
	s1 += s2;
	return stoi(s1);
}
int small_num[]{5, 7, 11}; 
int main(){
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
    int n, m;
    cin >> n >> m;
    for(int i:small_num){
        if(n <= i && m >= i) cout << i << '\n';
    }
    for(int i = 10; i <= 99999; i++){ 
        int j = get_pal(i);
        if(n <= j && m >= j && is_prime(j)) cout << j << '\n';
    }

	return 0;
}
